/** Reimplementación Java Swing de SistemaRural-PE. */
public class App {
    static final Path DIR=Path.of("datos"), DATA=DIR.resolve("datos-java.enc"), KEY=DIR.resolve("clave-java.key"), EXPORT=DIR.resolve("exportaciones");
    static final DateTimeFormatter DMY=DateTimeFormatter.ofPattern("dd/MM/uuuu").withResolverStyle(ResolverStyle.STRICT);
    static final SecureRandom RNG=new SecureRandom();
    static Store store=new Store(); static User logged;
    enum Permission { PATIENT_VIEW,PATIENT_CREATE,PATIENT_EDIT,HISTORY_VIEW,HISTORY_EDIT,CARE_CREATE,DOCTOR_VIEW,DOCTOR_CREATE,APPT_VIEW,APPT_MANAGE,TICKET_CREATE,TICKET_STATE,REPORT_VIEW,USER_MANAGE }
    static final Map<String,Set<Permission>> ROLES=new LinkedHashMap<>();
    static {
        ROLES.put("ADMIN",EnumSet.of(Permission.PATIENT_VIEW,Permission.PATIENT_CREATE,Permission.PATIENT_EDIT,Permission.DOCTOR_VIEW,Permission.DOCTOR_CREATE,Permission.APPT_VIEW,Permission.APPT_MANAGE,Permission.TICKET_CREATE,Permission.TICKET_STATE,Permission.REPORT_VIEW,Permission.USER_MANAGE));
        ROLES.put("JEFE",EnumSet.of(Permission.PATIENT_VIEW,Permission.DOCTOR_VIEW,Permission.APPT_VIEW,Permission.REPORT_VIEW));
        ROLES.put("ADMISION",EnumSet.of(Permission.PATIENT_VIEW,Permission.PATIENT_CREATE,Permission.PATIENT_EDIT,Permission.DOCTOR_VIEW,Permission.APPT_VIEW,Permission.APPT_MANAGE,Permission.TICKET_CREATE,Permission.TICKET_STATE));
        ROLES.put("ESTADISTICA",EnumSet.of(Permission.PATIENT_VIEW,Permission.DOCTOR_VIEW,Permission.APPT_VIEW,Permission.REPORT_VIEW));
        Set<Permission> clinical=EnumSet.of(Permission.PATIENT_VIEW,Permission.HISTORY_VIEW,Permission.HISTORY_EDIT,Permission.CARE_CREATE,Permission.DOCTOR_VIEW,Permission.APPT_VIEW,Permission.TICKET_STATE);
        Set<Permission> clinicalReports=EnumSet.copyOf(clinical); clinicalReports.add(Permission.REPORT_VIEW);
        for(String r:List.of("MEDICO","OBSTETRA"))ROLES.put(r,EnumSet.copyOf(clinicalReports));
        ROLES.put("ENFERMERA",EnumSet.copyOf(clinical)); ROLES.put("ODONTOLOGO",EnumSet.copyOf(clinical)); ROLES.put("PSICOLOGO",EnumSet.copyOf(clinical)); ROLES.put("NUTRICIONISTA",EnumSet.copyOf(clinical));
        ROLES.put("TEC_ENFERMERIA",EnumSet.of(Permission.PATIENT_VIEW,Permission.DOCTOR_VIEW,Permission.APPT_VIEW,Permission.TICKET_STATE));
        ROLES.put("TEC_LABORATORIO",EnumSet.of(Permission.PATIENT_VIEW,Permission.DOCTOR_VIEW,Permission.APPT_VIEW));
        ROLES.put("TEC_FARMACIA",EnumSet.of(Permission.PATIENT_VIEW,Permission.DOCTOR_VIEW,Permission.APPT_VIEW));
    }
    static String roleName(String r){return switch(r){case "ADMIN"->"Administrador del sistema";case "JEFE"->"Jefe del establecimiento";case "ADMISION"->"Admisión";case "ESTADISTICA"->"Estadística e informática";case "MEDICO"->"Médico(a)";case "OBSTETRA"->"Obstetra";case "ENFERMERA"->"Enfermero(a)";case "ODONTOLOGO"->"Odontólogo(a)";case "PSICOLOGO"->"Psicólogo(a)";case "NUTRICIONISTA"->"Nutricionista";case "TEC_ENFERMERIA"->"Técnico(a) de enfermería";case "TEC_LABORATORIO"->"Técnico(a) de laboratorio";default->"Técnico(a) de farmacia";};}
    static boolean can(Permission p){return logged!=null&&ROLES.getOrDefault(logged.role,Set.of()).contains(p);}
    static void require(Permission p){if(!can(p))throw new IllegalArgumentException("Su usuario no tiene permiso para realizar esta acción.");}
    static void warn(String s){JOptionPane.showMessageDialog(null,s,"Aviso",JOptionPane.WARNING_MESSAGE);} static void info(String s){JOptionPane.showMessageDialog(null,s,"SistemaRural-PE",JOptionPane.INFORMATION_MESSAGE);}
    static String req(String s,String f){if(s==null||s.trim().isEmpty())throw new IllegalArgumentException("El campo «"+f+"» es obligatorio.");return s.trim();}
    static LocalDate date(String s,String f){try{return LocalDate.parse(req(s,f),DMY);}catch(DateTimeParseException e){throw new IllegalArgumentException(f+": use DD/MM/AAAA (ej. 17/05/1990).");}}
    static String mask(String s){return "****"+s.substring(Math.max(0,s.length()-4));}
    static String docKey(String type,String number){return type+":"+number.toUpperCase(Locale.ROOT);}

    static class Patient implements Serializable {private static final long serialVersionUID=1L;String type,doc,names,surnames,birth,address,phone,allergies="",history="";List<Visit> visits=new ArrayList<>();String full(){return surnames+", "+names;}String key(){return docKey(type,doc);}}
    static class Doctor implements Serializable {private static final long serialVersionUID=1L;String dni,names,surnames,cmp,specialty,phone;String full(){return surnames+", "+names;}}
    static class Visit implements Serializable {private static final long serialVersionUID=1L;String date,reason,diagnosis,cmp;}
    static class Appointment implements Serializable {private static final long serialVersionUID=1L;String id,docKey,cmp,date,time,state="RESERVADO";}
    static class Ticket implements Serializable {private static final long serialVersionUID=1L;String appointmentId,date,state="PENDIENTE";int number;}
    static class User implements Serializable {private static final long serialVersionUID=1L;String username,names,surnames,role,salt,hash,cmp="";boolean active=true,mustChange=false;int failures=0;long lockedUntil=0;String full(){return surnames+", "+names;}}
    static class Data implements Serializable {private static final long serialVersionUID=1L;List<Patient> patients=new ArrayList<>();List<Doctor> doctors=new ArrayList<>();List<Appointment> appointments=new ArrayList<>();List<Ticket> tickets=new ArrayList<>();List<User> users=new ArrayList<>();Map<String,Integer> ticketCounters=new HashMap<>();}

    static class Store {
        Data d=new Data();byte[] key;
        void load()throws Exception{Files.createDirectories(DIR);Files.createDirectories(EXPORT);if(Files.exists(KEY)){key=Files.readAllBytes(KEY);if(key.length!=32)throw new Exception("La clave local no es válida.");}else{key=new byte[32];RNG.nextBytes(key);Files.write(KEY,key);try{java.io.File kf=KEY.toFile();kf.setReadable(false,false);kf.setReadable(true,true);kf.setWritable(false,false);kf.setWritable(true,true);}catch(Exception ignored){}}if(Files.exists(DATA)){byte[] all=Files.readAllBytes(DATA);if(all.length<13)throw new Exception("Archivo de datos dañado.");byte[] iv=Arrays.copyOfRange(all,0,12),ct=Arrays.copyOfRange(all,12,all.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));try(ObjectInputStream in=new ObjectInputStream(new ByteArrayInputStream(c.doFinal(ct)))){d=(Data)in.readObject();if(d==null)d=new Data();}}}
        void save(){try{Files.createDirectories(DIR);ByteArrayOutputStream b=new ByteArrayOutputStream();try(ObjectOutputStream o=new ObjectOutputStream(b)){o.writeObject(d);}byte[] iv=new byte[12];RNG.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));byte[] ct=c.doFinal(b.toByteArray());Path tmp=DATA.resolveSibling(DATA.getFileName()+".tmp");try(OutputStream out=Files.newOutputStream(tmp)){out.write(iv);out.write(ct);}Files.move(tmp,DATA,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(Exception e){throw new RuntimeException("No se pudieron guardar los datos: "+e.getMessage(),e);}}
        Patient patient(String type,String doc){String k=docKey(type,doc);return d.patients.stream().filter(p->p.key().equals(k)).findFirst().orElseThrow(()->new IllegalArgumentException("No existe un paciente con ese documento."));}
        Doctor doctor(String cmp){return d.doctors.stream().filter(x->x.cmp.equalsIgnoreCase(cmp.trim())).findFirst().orElseThrow(()->new IllegalArgumentException("No existe un profesional con ese CMP."));}
        User user(String u){return d.users.stream().filter(x->x.username.equalsIgnoreCase(u)).findFirst().orElseThrow(()->new IllegalArgumentException("No existe ese usuario."));}
        void addPatient(Patient p){if(d.patients.stream().anyMatch(x->x.key().equals(p.key())))throw new IllegalArgumentException("Ya existe un paciente con ese documento.");d.patients.add(p);save();}
        String passwordHash(String pass,String salt){try{PBEKeySpec spec=new PBEKeySpec(pass.toCharArray(),Base64.getDecoder().decode(salt),600000,256);byte[] h=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();return Base64.getEncoder().encodeToString(h);}catch(Exception e){throw new RuntimeException(e);}}
        void addUser(String username,String names,String surnames,String pass,String role,String cmp,boolean must){String u=req(username,"usuario").toLowerCase();if(!u.matches("[a-z0-9._]{4,20}"))throw new IllegalArgumentException("El usuario debe tener de 4 a 20 caracteres (letras, números, punto o guion bajo).");if(d.users.stream().anyMatch(x->x.username.equals(u)))throw new IllegalArgumentException("El usuario ya existe.");validatePass(pass,u);if(!ROLES.containsKey(role))throw new IllegalArgumentException("Rol desconocido.");User x=new User();x.username=u;x.names=req(names,"nombres");x.surnames=req(surnames,"apellidos");x.role=role;x.cmp=cmp==null?"":cmp.trim();x.salt=randomSalt();x.hash=passwordHash(pass,x.salt);x.mustChange=must;d.users.add(x);save();}
        String randomSalt(){byte[] b=new byte[16];RNG.nextBytes(b);return Base64.getEncoder().encodeToString(b);}
        void validatePass(String p,String u){if(p==null||p.length()<8||p.length()>128||!p.matches(".*[A-Za-zÁÉÍÓÚáéíóú].*")||!p.matches(".*\\d.*")||p.equalsIgnoreCase(u))throw new IllegalArgumentException("La contraseña debe tener 8–128 caracteres, letras y números, y no ser igual al usuario.");}
        User auth(String username,String pass){User x=d.users.stream().filter(v->v.username.equalsIgnoreCase(username.trim())).findFirst().orElse(null);if(x==null){passwordHash(pass,randomSalt());throw new IllegalArgumentException("Usuario o contraseña incorrectos.");}if(!x.active)throw new IllegalArgumentException("Su cuenta está desactivada. Consulte al administrador.");long now=System.currentTimeMillis();if(now<x.lockedUntil)throw new IllegalArgumentException("Cuenta bloqueada temporalmente. Intente más tarde.");String h=passwordHash(pass,x.salt);if(!MessageDigest.isEqual(h.getBytes(StandardCharsets.UTF_8),x.hash.getBytes(StandardCharsets.UTF_8))){x.failures++;if(x.failures>=5){x.lockedUntil=now+300000;x.failures=0;}save();throw new IllegalArgumentException("Usuario o contraseña incorrectos."+(x.lockedUntil>now?" Cuenta bloqueada por 5 minutos.":" Intentos restantes: "+(5-x.failures)+"."));}x.failures=0;x.lockedUntil=0;save();return x;}
    }

    public static void main(String[] args){SwingUtilities.invokeLater(()->{try{store.load();login();}catch(Exception e){warn(e.getMessage());}});}
    static void login(){if(store.d.users.isEmpty()){JTextField u=new JTextField("admin"),n=new JTextField(),a=new JTextField();JPasswordField p=new JPasswordField();Object[] f={"Crear primer administrador", "Usuario:",u,"Nombres:",n,"Apellidos:",a,"Contraseña (mín. 8, letras y números):",p};if(JOptionPane.showConfirmDialog(null,f,"Configuración inicial",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{store.addUser(u.getText(),n.getText(),a.getText(),new String(p.getPassword()),"ADMIN","",false);}catch(Exception e){warn(e.getMessage());login();return;}}
        JTextField u=new JTextField();JPasswordField p=new JPasswordField();Object[] f={"Usuario:",u,"Contraseña:",p};if(JOptionPane.showConfirmDialog(null,f,"Inicio de sesión",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{logged=store.auth(u.getText(),new String(p.getPassword()));if(logged.mustChange)changePassword(true);new MainWindow().setVisible(true);}catch(Exception e){warn(e.getMessage());login();}}
    static void changePassword(boolean forced){JPasswordField old=new JPasswordField(),n=new JPasswordField(),c=new JPasswordField();Object[] f={"Contraseña actual:",old,"Nueva contraseña:",n,"Confirmar nueva contraseña:",c};if(JOptionPane.showConfirmDialog(null,f,"Cambiar contraseña",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION){if(forced)throw new IllegalArgumentException("Debe cambiar su contraseña para continuar.");return;}if(!MessageDigest.isEqual(store.passwordHash(new String(old.getPassword()),logged.salt).getBytes(StandardCharsets.UTF_8),logged.hash.getBytes(StandardCharsets.UTF_8)))throw new IllegalArgumentException("La contraseña actual es incorrecta.");String np=new String(n.getPassword());store.validatePass(np,logged.username);if(!np.equals(new String(c.getPassword())))throw new IllegalArgumentException("Las contraseñas no coinciden.");logged.salt=store.randomSalt();logged.hash=store.passwordHash(np,logged.salt);logged.mustChange=false;store.save();info("Contraseña actualizada.");}

    static class MainWindow extends JFrame {
        JTabbedPane tabs=new JTabbedPane();DefaultTableModel pm,dm,am,tm,rm,um;JTable pt,at,tt,ut;List<Patient> patientRows=new ArrayList<>();
        JComboBox<String> patientType=new JComboBox<>(new String[]{"DNI","CE"}); JTextField pTypeDoc=new JTextField("DNI",7),pDoc=new JTextField(12),pNames=new JTextField(12),pSurnames=new JTextField(12),pBirth=new JTextField(10),pAddress=new JTextField(12),pPhone=new JTextField(10),searchDoc=new JTextField(10);
        JComboBox<String> historyDocType=new JComboBox<>(new String[]{"DNI","CE"}); JTextField hDoc=new JTextField(10),hAllergy=new JTextField(16),hHistory=new JTextField(16),vReason=new JTextField(14),vDiagnosis=new JTextField(12),vDate=new JTextField(10);
        MainWindow(){setTitle("SistemaRural-PE · Posta Médica Rural (Java)");setSize(1320,820);setMinimumSize(new Dimension(1100,700));setLocationRelativeTo(null);setDefaultCloseOperation(EXIT_ON_CLOSE);setLayout(new BorderLayout());JPanel head=new JPanel(new BorderLayout());head.setBackground(new Color(31,79,119));JLabel title=new JLabel("  SistemaRural-PE · Posta Médica Rural");title.setForeground(Color.WHITE);title.setFont(title.getFont().deriveFont(Font.BOLD,20f));head.add(title,BorderLayout.WEST);JLabel who=new JLabel(logged.full()+" · "+roleName(logged.role)+"   ");who.setForeground(Color.WHITE);head.add(who,BorderLayout.EAST);add(head,BorderLayout.NORTH);add(tabs,BorderLayout.CENTER);
            tabs.addTab("Inicio",home());if(can(Permission.PATIENT_VIEW))tabs.addTab("Pacientes",patients());if(can(Permission.HISTORY_VIEW))tabs.addTab("Historia clínica",history());if(can(Permission.DOCTOR_VIEW))tabs.addTab("Profesionales",doctors());if(can(Permission.APPT_VIEW))tabs.addTab("Citas y turnos",appointments());if(can(Permission.REPORT_VIEW))tabs.addTab("Reportes",reports());if(can(Permission.USER_MANAGE))tabs.addTab("Usuarios",users());refreshAll();}
        JPanel home(){JPanel p=new JPanel(new BorderLayout());JLabel welcome=new JLabel("<html><div style='padding:25px'><h1>Bienvenido(a) a SistemaRural-PE</h1><p>Gestión de pacientes, historias clínicas, profesionales, citas y turnos.</p><p>Sesión: "+logged.full()+"</p></div></html>");p.add(welcome,BorderLayout.NORTH);JPanel b=new JPanel(new FlowLayout(FlowLayout.RIGHT));b.add(btn("Cambiar contraseña",()->run(()->changePassword(false))));b.add(btn("Cerrar sesión",()->{dispose();logged=null;login();}));p.add(b,BorderLayout.SOUTH);return p;}
        JPanel patients(){JPanel p=new JPanel(new BorderLayout(8,8));JPanel form=new JPanel(new GridLayout(4,4,6,6));form.setBorder(BorderFactory.createTitledBorder("Datos del paciente"));JComboBox<String> type=patientType;form.add(new JLabel("Tipo de documento"));form.add(type);form.add(new JLabel("N.º documento"));form.add(pDoc);form.add(new JLabel("Nombres"));form.add(pNames);form.add(new JLabel("Apellidos"));form.add(pSurnames);form.add(new JLabel("Nacimiento (DD/MM/AAAA)"));form.add(pBirth);form.add(new JLabel("Dirección"));form.add(pAddress);form.add(new JLabel("Teléfono"));form.add(pPhone);p.add(form,BorderLayout.NORTH);
            JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));if(can(Permission.PATIENT_CREATE))actions.add(btn("Registrar",()->run(()->{Patient x=readPatient((String)type.getSelectedItem());store.addPatient(x);clearPatient();refreshPatients();info("Paciente registrado correctamente.");})));if(can(Permission.PATIENT_EDIT))actions.add(btn("Actualizar",()->run(()->{String doc=req(pDoc.getText(),"documento");Patient x=store.patient((String)type.getSelectedItem(),doc);x.names=req(pNames.getText(),"nombres");x.surnames=req(pSurnames.getText(),"apellidos");LocalDate bd=date(pBirth.getText(),"Fecha de nacimiento");validateBirth(bd);x.birth=bd.toString();x.address=pAddress.getText().trim();x.phone=pPhone.getText().trim();store.save();refreshPatients();info("Paciente actualizado.");})));actions.add(new JLabel("Documento:"));actions.add(searchDoc);actions.add(btn("Buscar por DNI",()->run(()->{String s=Validaciones.documento("DNI",req(searchDoc.getText(),"DNI"));Patient x=store.patient("DNI",s);showPatient(x);info("Paciente encontrado.");})));actions.add(btn("Ver todos",this::refreshPatients));actions.add(btn("Limpiar formulario",()->{clearPatient();type.setSelectedItem("DNI");}));actions.add(btn("Descargar ficha (Excel)",()->run(()->exportPatient())));p.add(actions,BorderLayout.CENTER);
            pm=model("Documento","Paciente","Nacimiento","Teléfono","Dirección");pt=new JTable(pm);pt.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);pt.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&pt.getSelectedRow()>=0){int row=pt.convertRowIndexToModel(pt.getSelectedRow());if(row>=0&&row<patientRows.size()){Patient x=patientRows.get(row);type.setSelectedItem(x.type);showPatient(x);}}});p.add(new JScrollPane(pt),BorderLayout.SOUTH);return p;}
        Patient readPatient(String type){String d=req(pDoc.getText(),"documento");if(type.equals("DNI")&&!d.matches("\\d{8}"))throw new IllegalArgumentException("El DNI debe tener exactamente 8 dígitos.");if(type.equals("CE")&&!d.matches("[A-Za-z0-9]{9,12}"))throw new IllegalArgumentException("El Carné de Extranjería debe tener entre 9 y 12 caracteres alfanuméricos.");Patient x=new Patient();x.type=type;x.doc=d;x.names=req(pNames.getText(),"nombres");x.surnames=req(pSurnames.getText(),"apellidos");LocalDate bd=date(pBirth.getText(),"Fecha de nacimiento");validateBirth(bd);x.birth=bd.toString();x.address=pAddress.getText().trim();x.phone=pPhone.getText().trim();return x;}
        void validateBirth(LocalDate d){Validaciones.nacimiento(d);}
        void showPatient(Patient x){pDoc.setText(x.doc);pNames.setText(x.names);pSurnames.setText(x.surnames);pBirth.setText(LocalDate.parse(x.birth).format(DMY));pAddress.setText(x.address);pPhone.setText(x.phone);searchDoc.setText(x.doc);}
        void clearPatient(){for(JTextField f:List.of(pDoc,pNames,pSurnames,pBirth,pAddress,pPhone,searchDoc))f.setText("");if(pt!=null)pt.clearSelection();}
        void refreshPatients(){if(pm==null)return;pm.setRowCount(0);patientRows=store.d.patients.stream().sorted(Comparator.comparing(Patient::full)).collect(Collectors.toCollection(ArrayList::new));for(Patient x:patientRows)pm.addRow(new Object[]{mask(x.doc),x.full(),LocalDate.parse(x.birth).format(DMY),x.phone,x.address});}
        void exportPatient()throws Exception{String type=patientType.getSelectedItem().toString();String d=req(searchDoc.getText(),"documento");Patient x=store.patient(type,Validaciones.documento(type,d));LinkedHashMap<String,List<List<String>>> sheets=new LinkedHashMap<>();List<List<String>> personal=new ArrayList<>();personal.add(List.of("Campo","Dato"));personal.add(List.of("Tipo de documento",x.type));personal.add(List.of("Documento",mask(x.doc)));personal.add(List.of("Apellidos y nombres",x.full()));personal.add(List.of("Nacimiento",LocalDate.parse(x.birth).format(DMY)));personal.add(List.of("Dirección",x.address));personal.add(List.of("Teléfono",x.phone));if(can(Permission.HISTORY_VIEW)){personal.add(List.of("Alergias",x.allergies));personal.add(List.of("Antecedentes",x.history));}sheets.put("Paciente",personal);List<List<String>> visits=new ArrayList<>();visits.add(List.of("Fecha","Motivo","Diagnóstico CIE-10","CMP"));for(Visit v:x.visits)visits.add(List.of(LocalDate.parse(v.date).format(DMY),v.reason,v.diagnosis,v.cmp));if(can(Permission.HISTORY_VIEW))sheets.put("Atenciones",visits);List<List<String>> appointments=new ArrayList<>();appointments.add(List.of("Fecha","Hora","Profesional","Estado"));for(Appointment q:store.d.appointments)if(q.docKey.equals(x.key())){Doctor dr=store.d.doctors.stream().filter(z->z.cmp.equals(q.cmp)).findFirst().orElse(null);appointments.add(List.of(LocalDate.parse(q.date).format(DMY),q.time,dr==null?"":dr.full(),q.state));}sheets.put("Citas",appointments);Path out=EXPORT.resolve("ficha_"+x.type+"_"+mask(x.doc).replace("*","x")+"_"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"))+".xlsx");ExcelWriter.write(out,sheets);info("Ficha Excel exportada en: "+out.toAbsolutePath());}
        JPanel history(){JPanel p=new JPanel(new BorderLayout(8,8));JPanel top=new JPanel(new GridLayout(2,4,5,5));top.setBorder(BorderFactory.createTitledBorder("Historia clínica del paciente"));top.add(new JLabel("Tipo de documento"));top.add(historyDocType);top.add(new JLabel("N.º documento"));top.add(hDoc);top.add(new JLabel("Alergias"));top.add(hAllergy);top.add(new JLabel("Antecedentes"));top.add(hHistory);JPanel histButtons=new JPanel(new FlowLayout(FlowLayout.LEFT));histButtons.add(btn("Cargar historia",()->run(()->{Patient x=store.patient(historyDocType.getSelectedItem().toString(),Validaciones.documento(historyDocType.getSelectedItem().toString(),req(hDoc.getText(),"documento")));hAllergy.setText(x.allergies);hHistory.setText(x.history);refreshVisits(x);})));histButtons.add(btn("Guardar historia",()->run(()->{require(Permission.HISTORY_EDIT);Patient x=store.patient(historyDocType.getSelectedItem().toString(),Validaciones.documento(historyDocType.getSelectedItem().toString(),req(hDoc.getText(),"documento")));x.allergies=hAllergy.getText().trim();x.history=hHistory.getText().trim();store.save();info("Historia clínica actualizada.");})));p.add(top,BorderLayout.NORTH);
            JPanel mid=new JPanel(new BorderLayout());mid.add(histButtons,BorderLayout.NORTH);JPanel f=new JPanel();f.setBorder(BorderFactory.createTitledBorder("Registrar atención"));JTextField cmp=new JTextField(8);for(Component c:new Component[]{new JLabel("CMP profesional"),cmp,new JLabel("Fecha DD/MM/AAAA"),vDate,new JLabel("Motivo"),vReason,new JLabel("Diagnóstico CIE-10"),vDiagnosis,btn("Registrar atención",()->run(()->{require(Permission.CARE_CREATE);Patient x=store.patient(historyDocType.getSelectedItem().toString(),Validaciones.documento(historyDocType.getSelectedItem().toString(),req(hDoc.getText(),"documento")));Doctor dr=store.doctor(req(cmp.getText(),"CMP"));LocalDate dt=vDate.getText().isBlank()?LocalDate.now():date(vDate.getText(),"Fecha de atención");if(dt.isAfter(LocalDate.now())||dt.isBefore(LocalDate.parse(x.birth)))throw new IllegalArgumentException("La fecha de atención debe estar entre el nacimiento y hoy.");Visit v=new Visit();v.date=dt.toString();v.reason=req(vReason.getText(),"motivo");v.diagnosis=req(vDiagnosis.getText(),"diagnóstico CIE-10");Validaciones.cie10(v.diagnosis);v.cmp=dr.cmp;x.visits.add(v);store.save();refreshVisits(x);vReason.setText("");vDiagnosis.setText("");vDate.setText("");info("Atención registrada.");}))})f.add(c);mid.add(f,BorderLayout.CENTER);rm=model("Fecha","Motivo","Diagnóstico CIE-10","CMP");mid.add(new JScrollPane(new JTable(rm)),BorderLayout.SOUTH);p.add(mid,BorderLayout.CENTER);return p;}
        void refreshVisits(Patient x){if(rm==null)return;rm.setRowCount(0);for(Visit v:x.visits)rm.addRow(new Object[]{LocalDate.parse(v.date).format(DMY),v.reason,v.diagnosis,v.cmp});}
        JPanel doctors(){JPanel p=new JPanel(new BorderLayout());JTextField dni=new JTextField(9),n=new JTextField(12),a=new JTextField(12),cmp=new JTextField(8),sp=new JTextField(12),ph=new JTextField(10);JPanel f=new JPanel(new GridLayout(2,6,5,5));f.setBorder(BorderFactory.createTitledBorder("Registrar profesional de salud"));for(Component c:new Component[]{new JLabel("DNI"),dni,new JLabel("Nombres"),n,new JLabel("Apellidos"),a,new JLabel("CMP"),cmp,new JLabel("Especialidad"),sp,new JLabel("Teléfono"),ph})f.add(c);p.add(f,BorderLayout.NORTH);dm=model("CMP","Profesional","Especialidad","Teléfono");p.add(new JScrollPane(new JTable(dm)),BorderLayout.CENTER);if(can(Permission.DOCTOR_CREATE))p.add(btn("Registrar profesional",()->run(()->{if(!dni.getText().matches("\\d{8}"))throw new IllegalArgumentException("DNI del profesional: 8 dígitos.");Doctor x=new Doctor();x.dni=dni.getText();x.names=req(n.getText(),"nombres");x.surnames=req(a.getText(),"apellidos");x.cmp=req(cmp.getText(),"CMP");x.specialty=req(sp.getText(),"especialidad");x.phone=ph.getText().trim();if(store.d.doctors.stream().anyMatch(v->v.cmp.equals(x.cmp)))throw new IllegalArgumentException("CMP ya registrado.");store.d.doctors.add(x);store.save();refreshDoctors();for(JTextField z:List.of(dni,n,a,cmp,sp,ph))z.setText("");info("Profesional registrado.");})),BorderLayout.SOUTH);return p;}
        void refreshDoctors(){if(dm==null)return;dm.setRowCount(0);store.d.doctors.stream().sorted(Comparator.comparing(Doctor::full)).forEach(x->dm.addRow(new Object[]{x.cmp,x.full(),x.specialty,x.phone}));}
        JPanel appointments(){JPanel p=new JPanel(new BorderLayout(6,6));JComboBox<String> appointmentDocType=new JComboBox<>(new String[]{"DNI","CE"});JTextField d=new JTextField(11),cmp=new JTextField(8),dt=new JTextField(10),timeInput=new JTextField("08:00",6);JPanel f=new JPanel();f.setBorder(BorderFactory.createTitledBorder("Agendar cita · lunes a sábado · turnos de 30 minutos"));for(Component c:new Component[]{new JLabel("Tipo documento"),appointmentDocType,new JLabel("N.º documento"),d,new JLabel("CMP profesional"),cmp,new JLabel("Fecha DD/MM/AAAA"),dt,new JLabel("Hora HH:MM"),timeInput})f.add(c);if(can(Permission.APPT_MANAGE))f.add(btn("Agendar",()->run(()->{String docType=appointmentDocType.getSelectedItem().toString();Patient pt=store.patient(docType,Validaciones.documento(docType,req(d.getText(),"documento")));Doctor dr=store.doctor(req(cmp.getText(),"CMP"));LocalDate day=date(dt.getText(),"Fecha");String time=req(timeInput.getText(),"Hora");validateAppointment(pt,dr,day,time);Appointment q=new Appointment();q.id=UUID.randomUUID().toString().substring(0,8);q.docKey=pt.key();q.cmp=dr.cmp;q.date=day.toString();q.time=time;store.d.appointments.add(q);store.save();refreshAppointments();d.setText("");cmp.setText("");dt.setText("");info("Cita agendada: "+q.id);})));p.add(f,BorderLayout.NORTH);am=model("Código","Fecha","Hora","Documento","Paciente","Profesional","Estado");at=new JTable(am);at.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);p.add(new JScrollPane(at),BorderLayout.CENTER);JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));if(can(Permission.APPT_MANAGE))b.add(btn("Cancelar cita",()->run(()->{Appointment q=selectedAppointment();if(q.state.equals("CANCELADA"))throw new IllegalArgumentException("La cita ya está cancelada.");q.state="CANCELADA";store.save();refreshAppointments();})));if(can(Permission.TICKET_CREATE))b.add(btn("Emitir ticket",()->run(()->{Appointment q=selectedAppointment();if(q.state.equals("CANCELADA"))throw new IllegalArgumentException("La cita está cancelada.");if(store.d.tickets.stream().anyMatch(t->t.appointmentId.equals(q.id)))throw new IllegalArgumentException("La cita ya tiene ticket.");int num=store.d.ticketCounters.merge(q.date,1,Integer::sum);Ticket t=new Ticket();t.appointmentId=q.id;t.date=q.date;t.number=num;store.d.tickets.add(t);store.save();refreshTickets();info("Ticket emitido: "+num);})));if(can(Permission.TICKET_STATE)){for(String s:List.of("EN_ATENCION","COMPLETADO","NO_ASISTIO"))b.add(btn(s,()->run(()->{Appointment q=selectedAppointment();if(s.equals("NO_ASISTIO")&&LocalDateTime.of(LocalDate.parse(q.date),LocalTime.parse(q.time)).isAfter(LocalDateTime.now()))throw new IllegalArgumentException("Aún no llega la hora de la cita.");if(q.state.equals("CANCELADA"))throw new IllegalArgumentException("La cita está cancelada.");q.state=s;store.d.tickets.stream().filter(t->t.appointmentId.equals(q.id)).forEach(t->t.state=s);store.save();refreshAppointments();refreshTickets();})));}p.add(b,BorderLayout.SOUTH);
            JPanel outer=new JPanel(new BorderLayout());outer.add(p,BorderLayout.CENTER);tm=model("Ticket","Fecha","Código cita","Estado");tt=new JTable(tm);JPanel tickets=new JPanel(new BorderLayout());tickets.setBorder(BorderFactory.createTitledBorder("Tickets de turno"));tickets.add(new JScrollPane(tt),BorderLayout.CENTER);tickets.setPreferredSize(new Dimension(300,150));outer.add(tickets,BorderLayout.SOUTH);return outer;}
        void validateAppointment(Patient p,Doctor d,LocalDate day,String time){Validaciones.cita(day,time);for(Appointment q:store.d.appointments)if(!q.state.equals("CANCELADA")&&q.date.equals(day.toString())&&q.time.equals(time)&&(q.cmp.equals(d.cmp)||q.docKey.equals(p.key())))throw new IllegalArgumentException("El paciente o profesional ya tiene una cita a esa hora.");long count=store.d.appointments.stream().filter(q->!q.state.equals("CANCELADA")&&q.date.equals(day.toString())&&q.cmp.equals(d.cmp)&&((LocalTime.parse(q.time).isBefore(LocalTime.NOON)&&LocalTime.parse(time).isBefore(LocalTime.NOON))||(!LocalTime.parse(q.time).isBefore(LocalTime.NOON)&&!LocalTime.parse(time).isBefore(LocalTime.NOON)))).count();if(count>=8)throw new IllegalArgumentException("No hay cupos disponibles para ese turno.");}
        Appointment selectedAppointment(){int r=at.getSelectedRow();if(r<0)throw new IllegalArgumentException("Seleccione una cita de la tabla.");String id=(String)am.getValueAt(at.convertRowIndexToModel(r),0);return store.d.appointments.stream().filter(q->q.id.equals(id)).findFirst().orElseThrow();}
        void refreshAppointments(){if(am==null)return;am.setRowCount(0);store.d.appointments.stream().sorted(Comparator.comparing((Appointment q)->q.date).thenComparing(q->q.time)).forEach(q->{Patient pt=store.d.patients.stream().filter(x->x.key().equals(q.docKey)).findFirst().orElse(null);Doctor dr=store.d.doctors.stream().filter(x->x.cmp.equals(q.cmp)).findFirst().orElse(null);am.addRow(new Object[]{q.id,LocalDate.parse(q.date).format(DMY),q.time,pt==null?"":mask(pt.doc),pt==null?"":pt.full(),dr==null?"":dr.full(),(q.state.equals("RESERVADO")&&LocalDateTime.of(LocalDate.parse(q.date),LocalTime.parse(q.time)).plusMinutes(30).isBefore(LocalDateTime.now()))?"VENCIDA (sin atender)":q.state});});refreshTickets();}
        void refreshTickets(){if(tm==null)return;tm.setRowCount(0);store.d.tickets.stream().sorted(Comparator.comparing((Ticket t)->t.date).thenComparingInt(t->t.number)).forEach(t->tm.addRow(new Object[]{t.number,LocalDate.parse(t.date).format(DMY),t.appointmentId,t.state}));}
        JPanel reports(){JPanel p=new JPanel(new BorderLayout());JPanel top=new JPanel();JComboBox<String> kind=new JComboBox<>(new String[]{"Diario","Semanal","Mensual"});JTextField ref=new JTextField(LocalDate.now().format(DMY),10);JTextArea out=new JTextArea();out.setEditable(false);top.add(new JLabel("Tipo de reporte"));top.add(kind);top.add(new JLabel("Fecha de referencia"));top.add(ref);top.add(btn("Generar reporte",()->run(()->out.setText(makeReport((String)kind.getSelectedItem(),date(ref.getText(),"Fecha de referencia"))))));top.add(btn("Exportar Excel (.xlsx)",()->run(()->exportReport(out.getText()))));top.add(btn("Exportar TXT",()->run(()->{Path f=EXPORT.resolve("reporte_"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"))+".txt");Files.writeString(f,out.getText(),StandardCharsets.UTF_8);info("Reporte guardado: "+f.toAbsolutePath());})));p.add(top,BorderLayout.NORTH);p.add(new JScrollPane(out),BorderLayout.CENTER);return p;}
        String makeReport(String type,LocalDate ref){if(ref.isAfter(LocalDate.now()))throw new IllegalArgumentException("La fecha del reporte no puede ser futura.");LocalDate from,to;if(type.equals("Diario")){from=to=ref;}else if(type.equals("Semanal")){from=ref.with(DayOfWeek.MONDAY);to=from.plusDays(6);}else{from=ref.withDayOfMonth(1);to=ref.withDayOfMonth(ref.lengthOfMonth());}List<Appointment> qs=store.d.appointments.stream().filter(q->{LocalDate d=LocalDate.parse(q.date);return !d.isBefore(from)&&!d.isAfter(to);}).toList();long done=qs.stream().filter(q->q.state.equals("COMPLETADO")).count();long no=qs.stream().filter(q->q.state.equals("NO_ASISTIO")).count();Map<String,Long> diagnoses=store.d.patients.stream().flatMap(pt->pt.visits.stream()).filter(v->{LocalDate vd=LocalDate.parse(v.date);return !vd.isBefore(from)&&!vd.isAfter(to);}).collect(Collectors.groupingBy(v->v.diagnosis,Collectors.counting()));StringBuilder s=new StringBuilder("SISTEMARURAL-PE · REPORTE "+type.toUpperCase()+"\nPeriodo: "+from.format(DMY)+" al "+to.format(DMY)+"\n\nPacientes registrados: "+store.d.patients.size()+"\nProfesionales registrados: "+store.d.doctors.size()+"\nCitas del periodo: "+qs.size()+"\nAtenciones registradas: "+diagnoses.values().stream().mapToLong(Long::longValue).sum()+"\nCompletadas: "+done+"\nNo asistió: "+no+"\nCanceladas: "+qs.stream().filter(q->q.state.equals("CANCELADA")).count()+"\n\nTOP 5 PATOLOGÍAS (CIE-10)\n");diagnoses.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(5).forEach(e->s.append(e.getKey()).append(" | ").append(e.getValue()).append(" atenciones\n"));s.append("\nDETALLE DE CITAS\n");for(Appointment q:qs){Patient pt=store.d.patients.stream().filter(x->x.key().equals(q.docKey)).findFirst().orElse(null);Doctor dr=store.d.doctors.stream().filter(x->x.cmp.equals(q.cmp)).findFirst().orElse(null);s.append(LocalDate.parse(q.date).format(DMY)).append(" ").append(q.time).append(" | ").append(pt==null?"":pt.full()).append(" | ").append(dr==null?"":dr.full()).append(" | ").append(q.state).append("\n");}return s.toString();}
        void exportReport(String text)throws Exception{LinkedHashMap<String,List<List<String>>> sheets=new LinkedHashMap<>();List<List<String>> summary=new ArrayList<>();summary.add(List.of("Resumen del reporte"));for(String line:text.split("\\R"))summary.add(List.of(line));sheets.put("Resumen",summary);List<List<String>> patients=new ArrayList<>();patients.add(List.of("Tipo documento","Documento","Paciente","Nacimiento","Teléfono","Dirección"));for(Patient x:store.d.patients)patients.add(List.of(x.type,mask(x.doc),x.full(),LocalDate.parse(x.birth).format(DMY),x.phone,x.address));sheets.put("Pacientes",patients);List<List<String>> appointments=new ArrayList<>();appointments.add(List.of("Fecha","Hora","Documento","Paciente","Profesional","Estado"));for(Appointment q:store.d.appointments){Patient pt=store.d.patients.stream().filter(x->x.key().equals(q.docKey)).findFirst().orElse(null);Doctor dr=store.d.doctors.stream().filter(x->x.cmp.equals(q.cmp)).findFirst().orElse(null);appointments.add(List.of(LocalDate.parse(q.date).format(DMY),q.time,pt==null?"":mask(pt.doc),pt==null?"":pt.full(),dr==null?"":dr.full(),q.state));}sheets.put("Citas",appointments);Path f=EXPORT.resolve("reporte_"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"))+".xlsx");ExcelWriter.write(f,sheets);info("Archivo Excel exportado: "+f.toAbsolutePath());}
        JPanel users(){JPanel p=new JPanel(new BorderLayout());um=model("Usuario","Nombre","Rol","Colegiatura","Activo","Cambiar clave");ut=new JTable(um);p.add(new JScrollPane(ut),BorderLayout.CENTER);JPanel b=new JPanel();b.add(btn("Crear usuario",()->run(()->{JTextField u=new JTextField(),n=new JTextField(),a=new JTextField(),cmp=new JTextField();JPasswordField pw=new JPasswordField();JComboBox<String> role=new JComboBox<>(ROLES.keySet().toArray(String[]::new));Object[] f={"Usuario",u,"Nombres",n,"Apellidos",a,"Contraseña temporal",pw,"Rol",role,"CMP/Colegiatura (si corresponde)",cmp};if(JOptionPane.showConfirmDialog(this,f,"Nuevo usuario",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){store.addUser(u.getText(),n.getText(),a.getText(),new String(pw.getPassword()),(String)role.getSelectedItem(),cmp.getText(),true);refreshUsers();}})));b.add(btn("Activar / desactivar",()->run(()->{User u=selectedUser();if(u==logged)throw new IllegalArgumentException("No puede desactivar su propia cuenta.");if(u.role.equals("ADMIN")&&u.active&&store.d.users.stream().filter(x->x.role.equals("ADMIN")&&x.active).count()<=1)throw new IllegalArgumentException("Debe quedar al menos un administrador activo.");u.active=!u.active;store.save();refreshUsers();})));b.add(btn("Cambiar rol",()->run(()->{User u=selectedUser();String r=(String)JOptionPane.showInputDialog(this,"Seleccione rol:","Cambiar rol",JOptionPane.QUESTION_MESSAGE,null,ROLES.keySet().toArray(),u.role);if(r!=null){if(u.role.equals("ADMIN")&&u.active&&store.d.users.stream().filter(x->x.role.equals("ADMIN")&&x.active).count()<=1&&!r.equals("ADMIN"))throw new IllegalArgumentException("Debe quedar al menos un administrador activo.");u.role=r;store.save();refreshUsers();}})));b.add(btn("Restablecer contraseña",()->run(()->{User u=selectedUser();JPasswordField pw=new JPasswordField();if(JOptionPane.showConfirmDialog(this,pw,"Nueva contraseña temporal",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){String np=new String(pw.getPassword());store.validatePass(np,u.username);u.salt=store.randomSalt();u.hash=store.passwordHash(np,u.salt);u.mustChange=true;u.failures=0;u.lockedUntil=0;store.save();info("Contraseña restablecida; deberá cambiarla al ingresar.");}})));p.add(b,BorderLayout.SOUTH);return p;}
        User selectedUser(){int r=ut.getSelectedRow();if(r<0)throw new IllegalArgumentException("Seleccione un usuario.");String u=(String)um.getValueAt(ut.convertRowIndexToModel(r),0);return store.user(u);}
        void refreshUsers(){if(um==null)return;um.setRowCount(0);store.d.users.forEach(x->um.addRow(new Object[]{x.username,x.full(),roleName(x.role),x.cmp,x.active?"Sí":"No",x.mustChange?"Sí":"No"}));}
        void refreshAll(){refreshPatients();refreshDoctors();refreshAppointments();refreshUsers();}
        DefaultTableModel model(String...cols){return new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};}
        JButton btn(String s,Runnable r){JButton b=new JButton(s);b.addActionListener(e->r.run());return b;}
        void run(Throwing t){try{t.go();}catch(Exception e){warn(e.getMessage()==null?"Ocurrió un error.":e.getMessage());}}
        interface Throwing{void go()throws Exception;}
    }
}
